/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountTransferGlow, type TransferGlowOptions } from "../../components/transfer-glow/TransferGlowEngine.js";
import type { MotionController } from "../../components/transfer-glow/motion-runtime";

export function TransferGlow({ options, className }: { options?: TransferGlowOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountTransferGlow(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="transfer-glow" />;
}

